# Voice: warm and quiet. A capsule is a note to oneself; nothing here is a
# countdown, a score or a nudge. Lock-screen copy never names a mood, a date
# or anything the person wrote (PRD 15-permissions, 12-notifications).

# ---- entry (Sanctuary) and list ---------------------------------------------
s("capsules_title", "Future you", "Title of the time-capsules area (Sanctuary section and the capsules list). Notes the person seals for their future self.", "భవిష్యత్తులో మీరు", "Future you", hi="भविष्य के आप", hl="Future you")
s("capsules_emptyBody", "Write to future you. Seal it for a date, or for a feeling.", "Empty state of the capsules list and the Sanctuary entry (PRD 14-states). Inviting, never pushy.", "భవిష్యత్తులోని మీకు రాయండి. ఒక తేదీ కోసం, లేదా ఒక భావన కోసం దాచిపెట్టండి.", "Future lo unna meeku raayandi. Oka date kosam, leda oka feeling kosam daachi pettandi.", hi="भविष्य के आपके लिए कुछ लिखें। इसे किसी तारीख के लिए सील करें, या किसी एहसास के लिए।", hl="Future you ke liye kuch likhein. Ise kisi date ke liye seal karein, ya kisi feeling ke liye.")
s("capsules_emptyCta", "Seal your first capsule", "Button in the empty capsules list that opens the composer (PRD 14-states).", "మీ మొదటి క్యాప్సూల్ దాచిపెట్టండి", "Mee first capsule seal cheyandi", hi="अपना पहला कैप्सूल सील करें", hl="Apna pehla capsule seal karein")
s("capsules_new", "Write a capsule", "Button that opens the capsule composer when the person already has capsules.", "ఒక క్యాప్సూల్ రాయండి", "Oka capsule raayandi", hi="कैप्सूल लिखें", hl="Capsule likhein")
s("capsules_entryCount", "{count, plural, =0{Nothing sealed yet} =1{1 capsule sealed} other{{count} capsules sealed}}", "Sanctuary entry: how many capsules are sealed (waiting).", "{count, plural, =0{ఇంకా ఏదీ దాచలేదు} =1{1 క్యాప్సూల్ దాచారు} other{{count} క్యాప్సూల్స్ దాచారు}}", "{count, plural, =0{Inka emi daachaledu} =1{1 capsule daachaaru} other{{count} capsules daachaaru}}", INT("count"), hi="{count, plural, =0{अभी कुछ सील नहीं हुआ} =1{1 कैप्सूल सील है} other{{count} कैप्सूल सील हैं}}", hl="{count, plural, =0{Abhi kuch seal nahi hua} =1{1 capsule seal hai} other{{count} capsules seal hain}}")
s("capsules_entryReady", "{count, plural, =1{1 is ready to open} other{{count} are ready to open}}", "Sanctuary entry: capsules whose time has come. Calm, no urgency.", "{count, plural, =1{1 తెరవడానికి సిద్ధంగా ఉంది} other{{count} తెరవడానికి సిద్ధంగా ఉన్నాయి}}", "{count, plural, =1{1 open cheyyadaaniki ready ga undi} other{{count} open cheyyadaaniki ready ga unnaayi}}", INT("count"), hi="{count, plural, =1{1 खुलने के लिए तैयार है} other{{count} खुलने के लिए तैयार हैं}}", hl="{count, plural, =1{1 khulne ke liye taiyaar hai} other{{count} khulne ke liye taiyaar hain}}")
s("capsules_sectionReady", "Ready to open", "List section: capsules that can be opened now.", "తెరవడానికి సిద్ధం", "Open cheyyadaaniki ready", hi="खुलने के लिए तैयार", hl="Khulne ke liye taiyaar")
s("capsules_sectionSealed", "Sealed", "List section: capsules still sealed.", "దాచినవి", "Seal chesinavi", hi="सील किए हुए", hl="Sealed")
s("capsules_sectionOpened", "Opened", "List section: capsules already opened (they can be read again).", "తెరిచినవి", "Open chesinavi", hi="खुले हुए", hl="Khule hue")
s("capsules_sealedUntil", "Sealed until {date}. It'll keep.", "A sealed date capsule (PRD 14-states). date = e.g. '12 Oct 2027'. Reassuring: it is safe and waiting.", "{date} వరకు దాచి ఉంది. భద్రంగా ఉంటుంది.", "{date} varaku seal ayyi undi. Bhadranga untundi.", STR("date"), hi="{date} तक सील है। यह सुरक्षित रहेगा।", hl="{date} tak seal hai. Yeh safe rahega.")
s("capsules_waitingFeeling", "Waiting for a feeling", "A sealed mood-trigger capsule in the list. Never names the feeling here.", "ఒక భావన కోసం ఎదురుచూస్తోంది", "Oka feeling kosam wait chestondi", hi="किसी एहसास का इंतज़ार", hl="Kisi feeling ka intezaar")
s("capsules_readyRow", "Ready when you are", "A capsule in the list that can be opened now.", "మీరు సిద్ధమైనప్పుడు తెరవండి", "Meeru ready ainappudu open cheyandi", hi="जब आप तैयार हों", hl="Jab aap taiyaar hon")
s("capsules_untitled", "A capsule from {date}", "Shown instead of a title when the person left the title empty. date = the day it was sealed.", "{date} నాటి క్యాప్సూల్", "{date} naati capsule", STR("date"), hi="{date} का एक कैप्सूल", hl="{date} ka ek capsule")
s("capsules_lockedTitle", "A sealed capsule", "Shown instead of the title when this phone can't read it yet (e.g. a new phone before the key arrives).", "దాచిన ఒక క్యాప్సూల్", "Seal chesina oka capsule", hi="एक सील किया हुआ कैप्सूल", hl="Ek sealed capsule")
s("capsules_sealedOn", "Sealed {date}", "When a capsule was sealed. date = e.g. '8 Oct 2026'.", "{date}న దాచారు", "{date} na seal chesaaru", STR("date"), hi="{date} को सील किया", hl="{date} ko seal kiya")
s("capsules_openedOn", "Opened {date}", "When a capsule was opened. date = e.g. '8 Oct 2027'.", "{date}న తెరిచారు", "{date} na open chesaaru", STR("date"), hi="{date} को खोला", hl="{date} ko khola")
s("capsules_draftTitle", "Your draft is here", "Card in the list: an unsealed capsule draft kept on this phone.", "మీ డ్రాఫ్ట్ ఇక్కడే ఉంది", "Mee draft ikkade undi", hi="आपका ड्राफ़्ट यहाँ है", hl="Aapka draft yahan hai")
s("capsules_draftBody", "Pick up where you left off.", "Under 'Your draft is here'.", "ఆపిన చోటు నుండి కొనసాగించండి.", "Aapina chotu nundi continue cheyandi.", hi="जहाँ छोड़ा था, वहीं से आगे लिखें।", hl="Jahan chhoda tha, wahin se aage likhein.")

