s("capsules_composeTitle", "Write to future you", "Title of the capsule composer.", "భవిష్యత్తులోని మీకు రాయండి", "Future lo unna meeku raayandi", hi="भविष्य के आपके लिए लिखें", hl="Future you ke liye likhein")
s("capsules_titleLabel", "Title", "Capsule title field (up to 60 characters).", "శీర్షిక", "Title", hi="टाइटल", hl="Title")
s("capsules_titleHelper", "Shown on the capsule while it's sealed.", "Helper under the title field: the title is the only thing visible before it opens.", "దాచి ఉన్నప్పుడు క్యాప్సూల్ మీద ఇది కనిపిస్తుంది.", "Seal ayyi unnappudu capsule meeda idi kanipistundi.", hi="सील रहने तक कैप्सूल पर यही दिखेगा।", hl="Seal rehne tak capsule par yahi dikhega.")
s("capsules_textLabel", "Your note", "Capsule text field (up to 2,000 characters).", "మీ నోట్", "Mee note", hi="आपका नोट", hl="Aapka note")
s("capsules_textHelper", "Only you will read this, when it opens.", "Helper under the capsule text field. Private.", "ఇది తెరుచుకున్నప్పుడు మీరు మాత్రమే చదువుతారు.", "Idi open ainappudu meeru maatrame chaduvutaaru.", hi="खुलने पर यह सिर्फ़ आपके लिए होगा।", hl="Khulne par yeh sirf aapke liye hoga.")
s("capsules_photosTitle", "Photos", "Section header for capsule photos.", "ఫోటోలు", "Photos", hi="फ़ोटो", hl="Photos")
s("capsules_addPhoto", "Add a photo", "Opens the system photo picker (no permission needed).", "ఒక ఫోటో జోడించండి", "Oka photo add cheyandi", hi="फ़ोटो जोड़ें", hl="Photo add karein")
s("capsules_photoHint", "Up to 3. Location and camera details are removed.", "Under 'Add a photo': at most 3 photos; EXIF/GPS are stripped on the phone.", "3 వరకు. లొకేషన్, కెమెరా వివరాలు తీసేస్తాం.", "3 varaku. Location, camera details teesestaam.", hi="ज़्यादा से ज़्यादा 3। लोकेशन और कैमरे की जानकारी हटा दी जाती है।", hl="Zyada se zyada 3. Location aur camera details hata di jaati hain.")
s("capsules_photoAdding", "Adding your photo…", "While a picked photo is resized and cleaned on the phone.", "మీ ఫోటో జోడిస్తున్నాం…", "Mee photo add chestunnaam…", hi="आपकी फ़ोटो जोड़ी जा रही है…", hl="Aapki photo add ho rahi hai…")
s("capsules_photoFailed", "That photo couldn't be added. Try another one.", "A picked photo could not be read or stored. Calm, no blame.", "ఆ ఫోటోను జోడించలేకపోయాం. ఇంకొకటి ప్రయత్నించండి.", "Aa photo add cheyyalekapoyaam. Inkokati try cheyandi.", hi="यह फ़ोटो नहीं जुड़ पाई। कोई दूसरी आज़माएँ।", hl="Yeh photo add nahi ho payi. Koi doosri try karein.")
s("capsules_photoRemove", "Remove photo {index}", "Screen-reader label / tooltip of a photo's remove button.", "ఫోటో {index} తీసేయండి", "Photo {index} teeseyandi", INT("index"), hi="फ़ोटो {index} हटाएँ", hl="Photo {index} hatayein")
s("capsules_photoSemantic", "Photo {index} of {count}", "Screen-reader label of a capsule photo.", "{count}లో ఫోటో {index}", "{count} lo photo {index}", INT("index", "count"), hi="{count} में से फ़ोटो {index}", hl="{count} mein se photo {index}")
s("capsules_voiceHint", "Up to 2 minutes. Only you can hear it.", "Hint under the record button in the capsule composer: the 2-minute limit and that it is private.", "2 నిమిషాల వరకు. ఇది మీకు మాత్రమే వినిపిస్తుంది.", "2 nimishaala varaku. Idi meeku maatrame vinipistundi.", hi="ज़्यादा से ज़्यादा 2 मिनट। यह सिर्फ़ आपके लिए है।", hl="Zyada se zyada 2 minute. Yeh sirf aapke liye hai.")
s("capsules_voiceLimit", "That's the full two minutes, so recording stopped. Your voice note is ready.", "Calm note after a capsule recording stopped by itself at 2:00 (REQ-CAP-05).", "రెండు నిమిషాలు పూర్తయ్యాయి, అందుకే రికార్డింగ్ ఆగింది. మీ వాయిస్ నోట్ సిద్ధంగా ఉంది.", "Rendu nimishaalu purthayyaayi, anduke recording aagindi. Mee voice note ready ga undi.", hi="पूरे दो मिनट हो गए, इसलिए रिकॉर्डिंग रुक गई। आपका वॉइस नोट तैयार है।", hl="Poore do minute ho gaye, isliye recording ruk gayi. Aapka voice note taiyaar hai.")
s("capsules_unlockTitle", "When should it open?", "Section header: choose a date or a feeling.", "ఇది ఎప్పుడు తెరుచుకోవాలి?", "Idi eppudu open avvaali?", hi="यह कब खुले?", hl="Yeh kab khule?")
s("capsules_unlockDate", "On a date", "Choice: the capsule opens on a date.", "ఒక తేదీన", "Oka date na", hi="किसी तारीख को", hl="Kisi date par")
s("capsules_unlockFeeling", "For a feeling", "Choice: the capsule opens on the next check-in with a chosen mood.", "ఒక భావన కోసం", "Oka feeling kosam", hi="किसी एहसास के लिए", hl="Kisi feeling ke liye")
s("capsules_pickDate", "Pick a date", "Opens the date picker.", "తేదీ ఎంచుకోండి", "Date select cheyandi", hi="तारीख चुनें", hl="Date chunein")
s("capsules_changeDate", "Change date", "Opens the date picker again.", "తేదీ మార్చండి", "Date maarchandi", hi="तारीख बदलें", hl="Date badlein")
s("capsules_dateChosen", "Opens {date} at {time}", "The chosen unlock moment, e.g. 'Opens 12 Oct 2027 at 10:00 AM'.", "{date} {time}కి తెరుచుకుంటుంది", "{date} {time} ki open avutundi", STR("date", "time"), hi="{date} को {time} पर खुलेगा", hl="{date} ko {time} par khulega")
s("capsules_dateHelp", "Any day from a week to five years from now.", "The allowed range for a date capsule (REQ-CAP-01).", "ఒక వారం నుండి ఐదేళ్ల లోపు ఏ రోజైనా.", "Oka vaaram nundi aidu ella lopu e roju aina.", hi="आज से एक हफ़्ते से लेकर पाँच साल तक का कोई भी दिन।", hl="Aaj se ek hafte se lekar paanch saal tak ka koi bhi din.")
s("capsules_datePickerHelp", "It opens at 10:00 that day", "Heading inside the date picker.", "ఆ రోజు 10:00కి తెరుచుకుంటుంది", "Aa roju 10:00 ki open avutundi", hi="उस दिन 10:00 बजे खुलेगा", hl="Us din 10:00 baje khulega")
s("capsules_feelingHelp", "It can open from 24 hours after sealing, the next time you check in feeling this.", "How a mood capsule opens (REQ-CAP-02).", "దాచిన 24 గంటల తర్వాత నుండి, మీరు తదుపరి సారి ఇలా ఫీల్ అవుతూ చెక్-ఇన్ చేసినప్పుడు తెరుచుకోవచ్చు.", "Seal chesina 24 gantala tarvaata nundi, meeru next time ila feel avutu check-in chesinappudu open avvochu.", hi="सील करने के 24 घंटे बाद से, अगली बार यही एहसास होने पर चेक-इन करते ही यह खुल सकता है।", hl="Seal karne ke 24 ghante baad se, agli baar yahi feeling hone par check-in karte hi yeh khul sakta hai.")
s("capsules_anyQuadrant", "Any {quadrant} feeling", "Choice: any mood of a quadrant, e.g. 'Any Storm feeling'.", "ఏదైనా {quadrant} భావన", "Edaina {quadrant} feeling", STR("quadrant"), hi="{quadrant} वाला कोई भी एहसास", hl="Koi bhi {quadrant} feeling")
s("capsules_feelingChosen", "Waits for: {feeling}", "The chosen trigger (a mood name, or 'Any Storm feeling').", "దీని కోసం ఎదురుచూస్తుంది: {feeling}", "Deeni kosam wait chestundi: {feeling}", STR("feeling"), hi="इसका इंतज़ार: {feeling}", hl="Iska intezaar: {feeling}")
s("capsules_seal", "Seal it", "Seals the capsule (content can't change after this).", "దాచిపెట్టండి", "Seal cheyandi", hi="सील करें", hl="Seal karein")
s("capsules_needContent", "Add a few words, a voice note or a photo first.", "Seal tapped with nothing inside. Calm.", "ముందు కొన్ని మాటలు, ఒక వాయిస్ నోట్ లేదా ఒక ఫోటో జోడించండి.", "Mundu konni maatalu, oka voice note leda oka photo add cheyandi.", hi="पहले कुछ शब्द, एक वॉइस नोट या एक फ़ोटो जोड़ें।", hl="Pehle kuch shabd, ek voice note ya ek photo add karein.")
s("capsules_needUnlock", "Choose when it should open.", "Seal tapped without a date or feeling.", "ఇది ఎప్పుడు తెరుచుకోవాలో ఎంచుకోండి.", "Idi eppudu open avvaalo select cheyandi.", hi="चुनें कि यह कब खुले।", hl="Chunein ki yeh kab khule.")
s("capsules_sealFailed", "That didn't seal just now. Your capsule is still here. Try again.", "Sealing failed locally (e.g. storage). Nothing is lost.", "ఇప్పుడు దాచలేకపోయాం. మీ క్యాప్సూల్ ఇక్కడే ఉంది. మళ్ళీ ప్రయత్నించండి.", "Ippudu seal avvaledu. Mee capsule ikkade undi. Malli try cheyandi.", hi="अभी सील नहीं हो पाया। आपका कैप्सूल यहीं है। फिर से कोशिश करें।", hl="Abhi seal nahi ho paya. Aapka capsule yahin hai. Phir se try karein.")
s("capsules_sealedTitle", "Sealed", "Heading after sealing.", "దాచిపెట్టాం", "Seal ayyindi", hi="सील हो गया", hl="Seal ho gaya")
s("capsules_sealedFeeling", "Sealed. It'll wait for that feeling.", "After sealing a mood capsule.", "దాచిపెట్టాం. ఆ భావన కోసం ఎదురుచూస్తుంది.", "Seal chesaam. Aa feeling kosam wait chestundi.", hi="सील हो गया। यह उसी एहसास का इंतज़ार करेगा।", hl="Seal ho gaya. Yeh usi feeling ka intezaar karega.")
s("capsules_mediaLater", "Sealed and safe on this phone. Photos and voice back up when you're online.", "Sealed while offline, or media still uploading (PRD 14-states 'media upload failed').", "ఈ ఫోన్‌లో భద్రంగా దాచాం. మీరు ఆన్‌లైన్‌కి వచ్చాక ఫోటోలు, వాయిస్ బ్యాకప్ అవుతాయి.", "Ee phone lo bhadranga seal chesaam. Meeru online ki vachaaka photos, voice backup avutaayi.", hi="इस फ़ोन पर सील और सुरक्षित है। ऑनलाइन होने पर फ़ोटो और आवाज़ का बैकअप हो जाएगा।", hl="Is phone par sealed aur safe hai. Online hone par photos aur voice ka backup ho jayega.")
s("capsules_limitBody", "Free accounts keep 3 mood capsules waiting. Date capsules are unlimited.", "A 4th mood-trigger capsule (REQ-CAP-04, PRD 14-states). No paywall: offers a date instead.", "ఉచిత ఖాతాలో 3 మూడ్ క్యాప్సూల్స్ వరకు ఎదురుచూడగలవు. తేదీ క్యాప్సూల్స్‌కు పరిమితి లేదు.", "Free account lo 3 mood capsules varaku wait cheyyochu. Date capsules ki limit ledu.", hi="फ़्री अकाउंट में 3 मूड कैप्सूल इंतज़ार में रखे जा सकते हैं। तारीख वाले कैप्सूल की कोई सीमा नहीं है।", hl="Free account mein 3 mood capsules intezaar mein rakhe ja sakte hain. Date capsules ki koi limit nahi hai.")
s("capsules_limitPickDate", "Pick a date instead", "Switches a 4th mood capsule to a date capsule.", "బదులుగా ఒక తేదీ ఎంచుకోండి", "Badulu ga oka date select cheyandi", hi="इसके बदले तारीख चुनें", hl="Iske badle date chunein")
s("capsules_makeDate", "Make it a date capsule", "A mood capsule the server couldn't keep (limit): choose a date for it.", "దీన్ని తేదీ క్యాప్సూల్‌గా మార్చండి", "Deenni date capsule ga maarchandi", hi="इसे तारीख वाला कैप्सूल बनाएँ", hl="Ise date capsule banayein")
s("capsules_leaveTitle", "Keep this draft?", "Leaving the composer with something written.", "ఈ డ్రాఫ్ట్ ఉంచాలా?", "Ee draft unchaalaa?", hi="यह ड्राफ़्ट रखें?", hl="Yeh draft rakhein?")
s("capsules_leaveBody", "It stays on this phone until you seal it or let it go.", "Under 'Keep this draft?'.", "మీరు దాన్ని దాచే వరకు లేదా వదిలేసే వరకు ఇది ఈ ఫోన్‌లోనే ఉంటుంది.", "Meeru deenni seal chese varaku leda vadilese varaku idi ee phone lone untundi.", hi="जब तक आप इसे सील न करें या हटा न दें, यह इसी फ़ोन पर रहेगा।", hl="Jab tak aap ise seal na karein ya hata na dein, yeh isi phone par rahega.")
s("capsules_leaveEditing", "Keep editing", "Stay in the composer (default, focused).", "రాయడం కొనసాగించండి", "Raayadam continue cheyandi", hi="लिखते रहें", hl="Likhte rahein")
s("capsules_leaveKeep", "Keep draft", "Leave; the draft stays on this phone.", "డ్రాఫ్ట్ ఉంచండి", "Draft unchandi", hi="ड्राफ़्ट रखें", hl="Draft rakhein")
s("capsules_leaveDiscard", "Discard", "Leave and delete the draft.", "వదిలేయండి", "Vadileyandi", hi="हटा दें", hl="Hata dein")

# ---- a sealed capsule ----------------------------------------------------------
s("capsules_detailFeeling", "Waiting for a feeling: {feeling}.", "A sealed mood capsule's page (in the app only, never on the lock screen).", "ఒక భావన కోసం ఎదురుచూస్తోంది: {feeling}.", "Oka feeling kosam wait chestondi: {feeling}.", STR("feeling"), hi="किसी एहसास का इंतज़ार: {feeling}.", hl="Kisi feeling ka intezaar: {feeling}.")
s("capsules_detailArming", "It can open from {date}.", "A mood capsule sealed less than 24 hours ago. date = day and time it arms.", "{date} నుండి తెరుచుకోవచ్చు.", "{date} nundi open avvochu.", STR("date"), hi="यह {date} से खुल सकता है।", hl="Yeh {date} se khul sakta hai.")
s("capsules_detailNoEarly", "Sealed means sealed: it can't be opened early or changed.", "Why there is no 'open' button on a sealed capsule.", "దాచిందంటే దాచిందే: దీన్ని ముందుగా తెరవలేరు, మార్చలేరు.", "Seal ante seal: deenni mundugaa open cheyyaleru, maarchaleru.", hi="सील का मतलब सील: इसे न पहले खोला जा सकता है, न बदला जा सकता है।", hl="Seal matlab seal: ise na pehle khola ja sakta hai, na badla ja sakta hai.")
s("capsules_delete", "Delete capsule", "Deletes a capsule (never shows its content).", "క్యాప్సూల్ తొలగించండి", "Capsule delete cheyandi", hi="कैप्सूल डिलीट करें", hl="Capsule delete karein")
s("capsules_deleteTitle", "Delete this capsule?", "Confirmation before deleting.", "ఈ క్యాప్సూల్ తొలగించాలా?", "Ee capsule delete cheyyaalaa?", hi="यह कैप्सूल डिलीट करें?", hl="Yeh capsule delete karein?")
s("capsules_deleteBody", "It will be gone for good, without being opened.", "Deleting a sealed capsule.", "ఇది తెరవకుండానే శాశ్వతంగా పోతుంది.", "Idi open cheyyakundaane shaashvatanga potundi.", hi="यह बिना खुले हमेशा के लिए हट जाएगा।", hl="Yeh bina khule hamesha ke liye hat jayega.")
s("capsules_deleteBodyOpened", "It will be gone for good.", "Deleting an opened capsule.", "ఇది శాశ్వతంగా పోతుంది.", "Idi shaashvatanga potundi.", hi="यह हमेशा के लिए हट जाएगा।", hl="Yeh hamesha ke liye hat jayega.")
s("capsules_deleteConfirm", "Delete", "Confirms the deletion.", "తొలగించండి", "Delete cheyandi", hi="डिलीट करें", hl="Delete karein")
s("capsules_deleteKeep", "Keep it", "Cancels the deletion (default, focused).", "ఉంచండి", "Unchandi", hi="रहने दें", hl="Rehne dein")
s("capsules_deleted", "Capsule deleted.", "After a capsule was deleted.", "క్యాప్సూల్ తొలగించాం.", "Capsule delete chesaam.", hi="कैप्सूल डिलीट हो गया।", hl="Capsule delete ho gaya.")

# ---- mood trigger (in-app only, never a push) -----------------------------------
s("capsules_triggerTitle", "You left a note for a moment like this. Open now or later?", "Card after a check-in that matched a mood capsule (PRD 12-notifications, in-app only).", "ఇలాంటి క్షణం కోసం మీరు ఒక నోట్ రాసుకున్నారు. ఇప్పుడే తెరవాలా, తర్వాతా?", "Ilanti moment kosam meeru oka note raasukunnaru. Ippude open cheyyala, tarvatha na?", hi="ऐसे पल के लिए आपने एक नोट छोड़ा था। अभी खोलें या बाद में?", hl="Aise pal ke liye aapne ek note chhoda tha. Abhi kholein ya baad mein?")
s("capsules_holdTitle", "A note from past you is waiting. Open now, or later?", "After the support sheet, when a capsule matched a crisis-flagged check-in (F4 crisis collision rule). Gentle; 'Later' is fine.", "గతంలోని మీ నుండి ఒక నోట్ ఎదురుచూస్తోంది. ఇప్పుడే తెరవాలా, తర్వాతా?", "Gatam lo mee nundi oka note wait chestondi. Ippude open cheyyala, tarvatha na?", hi="पहले लिखा आपका एक नोट इंतज़ार में है। अभी खोलें, या बाद में?", hl="Pehle likha aapka ek note intezaar mein hai. Abhi kholein, ya baad mein?")
s("capsules_now", "Now", "Open the capsule now.", "ఇప్పుడే", "Ippude", hi="अभी", hl="Abhi")
s("capsules_later", "Later", "Keep it for later.", "తర్వాత", "Tarvatha", hi="बाद में", hl="Baad mein")

# ---- date unlock -----------------------------------------------------------------
s("capsules_readyTitle", "Something you sealed is ready to open.", "Home card and the local notification when a date capsule unlocks (PRD 12-notifications). Never a title, date or mood.", "మీరు దాచుకున్నది ఇప్పుడు తెరవొచ్చు.", "Meeru daachukunnadi ippudu open cheyyochu.", hi="आपने जो सील किया था, वह अब खुल सकता है।", hl="Aapne jo seal kiya tha, woh ab khul sakta hai.")
s("capsules_readyMore", "{count, plural, =1{1 capsule is ready.} other{{count} capsules are ready.}}", "Home card when several date capsules are ready.", "{count, plural, =1{1 క్యాప్సూల్ సిద్ధంగా ఉంది.} other{{count} క్యాప్సూల్స్ సిద్ధంగా ఉన్నాయి.}}", "{count, plural, =1{1 capsule ready ga undi.} other{{count} capsules ready ga unnaayi.}}", INT("count"), hi="{count, plural, =1{1 कैप्सूल तैयार है।} other{{count} कैप्सूल तैयार हैं।}}", hl="{count, plural, =1{1 capsule taiyaar hai.} other{{count} capsules taiyaar hain.}}")
s("capsules_readyOpen", "Open it", "Opens a capsule (Home card, a capsule's page, the hard-moment note).", "తెరవండి", "Open cheyandi", hi="खोलें", hl="Kholein")
s("capsules_channelName", "Capsules", "Android notification channel name (Settings).", "క్యాప్సూల్స్", "Capsules", hi="कैप्सूल", hl="Capsules")
s("capsules_notifyAskTitle", "Want to know when it opens?", "The one notification re-ask, after sealing a date capsule (PRD 15-permissions). Only 'Allow' shows the OS prompt.", "ఇది ఎప్పుడు తెరుచుకుంటుందో తెలుసుకోవాలనుకుంటున్నారా?", "Idi eppudu open avutundo telusukovaalanukuntunnaaraa?", hi="खुलने पर आपको बताया जाए?", hl="Khulne par aapko bataya jaye?")
s("capsules_notifyAskBody", "One quiet note on the day it opens. Nothing on your lock screen says what's inside.", "Under 'Want to know when it opens?'. Must promise: one note, nothing about the content on the lock screen.", "అది తెరుచుకునే రోజు ఒక్క నిశ్శబ్ద సందేశం. లోపల ఏముందో మీ లాక్ స్క్రీన్ ఎప్పుడూ చెప్పదు.", "Adi open ayye roju oka quiet note. Lopala emundo mee lock screen eppudu cheppadu.", hi="खुलने वाले दिन बस एक हल्का-सा नोट। आपकी लॉक स्क्रीन पर यह नहीं दिखेगा कि अंदर क्या है।", hl="Khulne wale din bas ek halka sa note. Lock screen par yeh nahi dikhega ki andar kya hai.")
s("capsules_channelDescription", "When something you sealed is ready to open.", "Android notification channel description.", "మీరు దాచుకున్నది తెరవడానికి సిద్ధమైనప్పుడు.", "Meeru daachukunnadi open cheyyadaaniki ready ainappudu.", hi="जब आपका सील किया हुआ कुछ खुलने के लिए तैयार हो।", hl="Jab aapka seal kiya hua kuch khulne ke liye taiyaar ho.")

# ---- opening ---------------------------------------------------------------------
s("capsules_hardMoment", "You wrote this during a hard moment. Open when you're ready.", "Before opening a capsule sealed during a hard moment (PRD F4). A help button sits with it.", "మీరు ఇది ఒక కష్టమైన సమయంలో రాశారు. మీరు సిద్ధమైనప్పుడు తెరవండి.", "Meeru idi oka kashtamaina samayam lo raasaaru. Meeru ready ainappudu open cheyandi.", hi="यह आपने एक मुश्किल घड़ी में लिखा था। जब आप तैयार हों, तब खोलें।", hl="Yeh aapne ek mushkil waqt mein likha tha. Jab aap taiyaar hon, tab kholein.")
s("capsules_skip", "Skip", "Skips the opening animation.", "దాటవేయండి", "Skip cheyandi", hi="छोड़ें", hl="Skip karein")
s("capsules_opening", "Opening your capsule", "Screen-reader label of the short opening animation.", "మీ క్యాప్సూల్ తెరుచుకుంటోంది", "Mee capsule open avutondi", hi="आपका कैप्सूल खुल रहा है", hl="Aapka capsule khul raha hai")
s("capsules_openedTitle", "From past you", "Heading of an opened capsule.", "గతంలోని మీ నుండి", "Gatam lo mee nundi", hi="बीते समय के आप से", hl="Past you se")
s("capsules_keepNextTime", "Keep for next time", "Re-arms a mood capsule so it can open again for the same feeling.", "తర్వాతి సారి కోసం ఉంచండి", "Next time kosam unchandi", hi="अगली बार के लिए रखें", hl="Agli baar ke liye rakhein")
s("capsules_keptNextTime", "It'll wait for that feeling again.", "After 'Keep for next time'.", "ఇది మళ్ళీ ఆ భావన కోసం ఎదురుచూస్తుంది.", "Idi malli aa feeling kosam wait chestundi.", hi="यह फिर से उसी एहसास का इंतज़ार करेगा।", hl="Yeh phir se usi feeling ka intezaar karega.")
s("capsules_voiceOffline", "Your capsule is open. The voice note arrives when you're back online.", "Opened offline; the voice note is only on the server (PRD 14-states).", "మీ క్యాప్సూల్ తెరుచుకుంది. మీరు మళ్ళీ ఆన్‌లైన్‌కి వచ్చాక వాయిస్ నోట్ వస్తుంది.", "Mee capsule open ayyindi. Meeru malli online ki vachaaka voice note vastundi.", hi="आपका कैप्सूल खुल गया है। ऑनलाइन वापस आने पर वॉइस नोट आ जाएगा।", hl="Aapka capsule khul gaya hai. Online wapas aane par voice note aa jayega.")
s("capsules_photosOffline", "The photos arrive when you're back online.", "Opened offline; the photos are only on the server.", "మీరు మళ్ళీ ఆన్‌లైన్‌కి వచ్చాక ఫోటోలు వస్తాయి.", "Meeru malli online ki vachaaka photos vastaayi.", hi="ऑनलाइन वापस आने पर फ़ोटो आ जाएँगी।", hl="Online wapas aane par photos aa jayengi.")
s("capsules_mediaFailed", "This couldn't be loaded just now. Try again in a moment.", "A capsule photo or voice note failed to load. Calm.", "ఇది ఇప్పుడు లోడ్ కాలేదు. కాసేపాగి మళ్ళీ ప్రయత్నించండి.", "Idi ippudu load avvaledu. Kaasepaagi malli try cheyandi.", hi="यह अभी लोड नहीं हो पाया। थोड़ी देर में फिर से कोशिश करें।", hl="Yeh abhi load nahi ho paya. Thodi der mein phir se try karein.")
s("capsules_retry", "Try again", "Retries loading capsule media.", "మళ్ళీ ప్రయత్నించండి", "Malli try cheyandi", hi="फिर से कोशिश करें", hl="Phir se try karein")
s("capsules_cantRead", "This capsule can't be read on this phone yet. It opens once you're back online.", "The data key isn't on this phone yet (new phone, offline).", "ఈ క్యాప్సూల్‌ను ఈ ఫోన్‌లో ఇంకా చదవలేం. మీరు ఆన్‌లైన్‌కి వచ్చాక తెరుచుకుంటుంది.", "Ee capsule ni ee phone lo inka chadavalemu. Meeru online ki vachaaka open avutundi.", hi="यह कैप्सूल अभी इस फ़ोन पर पढ़ा नहीं जा सकता। ऑनलाइन वापस आने पर यह खुल जाएगा।", hl="Yeh capsule abhi is phone par padha nahi ja sakta. Online wapas aane par yeh khul jayega.")

# ---- account deletion (features/account shows it) --------------------------------
s("capsules_accountDeletionCount", "{count, plural, =1{1 sealed capsule will be lost.} other{{count} sealed capsules will be lost.}}", "Delete-account confirmation: sealed (unopened) capsules that deletion removes (PRD F4 edge cases).", "{count, plural, =1{దాచిన 1 క్యాప్సూల్ పోతుంది.} other{దాచిన {count} క్యాప్సూల్స్ పోతాయి.}}", "{count, plural, =1{Seal chesina 1 capsule potundi.} other{Seal chesina {count} capsules potaayi.}}", INT("count"), hi="{count, plural, =1{सील किया हुआ 1 कैप्सूल हमेशा के लिए मिट जाएगा।} other{सील किए हुए {count} कैप्सूल हमेशा के लिए मिट जाएँगे।}}", hl="{count, plural, =1{Seal kiya hua 1 capsule hamesha ke liye mit jayega.} other{Seal kiye hue {count} capsules hamesha ke liye mit jayenge.}}")
